\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.1.0-rc.5 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"^0.1.0-rc.5 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.5 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"^0.1.0-rc.5 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-invariants\": \"^0.1.0-rc.5 || 0.2.1-rc.3\",\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-client-locale\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-store\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-test-runtime\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"workspace:^\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"workspace:^\",\n    \"@deepseek-ai/dsh-invariants\": \"workspace:^\",\n    \"@testing-library/react\": \"^16.1.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@deepseek-ai/cordis\": \"workspace:^\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/invariant.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.d.ts\",\n    \"cordis.patch.yml\"\n  ]\n}\n"
